functions.acquire_department_mutation_lock:
CREATE OR REPLACE FUNCTION public.acquire_department_mutation_lock()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM pg_advisory_xact_lock(904202607);
    RETURN NULL;
END;
$function$

functions.prevent_department_hierarchy_cycle:
CREATE OR REPLACE FUNCTION public.prevent_department_hierarchy_cycle()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    has_cycle BOOLEAN;
BEGIN
    IF NEW."parentId" IS NULL THEN
        RETURN NEW;
    END IF;
    IF NEW."parentId" = NEW."id" THEN
        RAISE EXCEPTION 'Department cannot be its own parent'
            USING ERRCODE = '23514';
    END IF;

    WITH RECURSIVE ancestors AS (
        SELECT department."id", department."parentId", ARRAY[department."id"] AS path
        FROM "departments" department
        WHERE department."id" = NEW."parentId"
        UNION ALL
        SELECT department."id", department."parentId", ancestors.path || department."id"
        FROM "departments" department
        JOIN ancestors ON department."id" = ancestors."parentId"
        WHERE NOT department."id" = ANY(ancestors.path)
    )
    SELECT EXISTS (
        SELECT 1 FROM ancestors WHERE "id" = NEW."id"
    ) INTO has_cycle;

    IF has_cycle THEN
        RAISE EXCEPTION 'Department hierarchy cycle detected'
            USING ERRCODE = '23514';
    END IF;
    RETURN NEW;
END;
$function$
